// Auto-generated meal dataset. Ingredient names are plain lowercase food names
// (e.g. "chicken breast") so they can be looked up in the USDA FoodData Central API.

export interface MealIngredient {
  /** Lowercase food name, suitable as a USDA search query. */
  name: string;
  /** Amount of this ingredient in one serving, in grams. */
  grams: number;
  /** Optional USDA fdcId. If set, it skips the name search in getIngredientNutritionPer100g. */
  fdcId?: number;
}

export interface Meal {
  id: number;
  name: string;
  description: string;
  ingredients: MealIngredient[];
  /** Total prep + cook time in minutes. */
  cookingTime: number;
  /** Estimated cost per serving in USD. */
  cost: number;
}

